/**
 * Scans app/prototypes/<slug>/metadata.json and public/thumbnails/ and writes
 * lib/registry.generated.ts. Runs automatically before dev and build, and at the
 * end of the thumbnail script. Never edit the generated file by hand.
 *
 *   npx tsx scripts/generate-registry.ts
 */
import fs from "node:fs"
import path from "node:path"

const root = process.cwd()
const prototypesDir = path.join(root, "app", "prototypes")
const thumbsDir = path.join(root, "public", "thumbnails")
const outFile = path.join(root, "lib", "registry.generated.ts")

const REQUIRED = ["title", "description", "tags", "createdAt", "updatedAt", "hidden", "public"] as const

const exists = (p: string) => fs.existsSync(p)
const thumb = (file: string) => (exists(path.join(thumbsDir, file)) ? `/thumbnails/${file}` : null)

const slugs = fs
  .readdirSync(prototypesDir, { withFileTypes: true })
  .filter((d) => d.isDirectory() && !d.name.startsWith("[") && !d.name.startsWith("_"))
  .map((d) => d.name)
  .filter((slug) => exists(path.join(prototypesDir, slug, "metadata.json")))
  .sort()

const errors: string[] = []
const entries = slugs.map((slug) => {
  const dir = path.join(prototypesDir, slug)
  let meta: Record<string, unknown> = {}
  try {
    meta = JSON.parse(fs.readFileSync(path.join(dir, "metadata.json"), "utf8"))
  } catch (e) {
    errors.push(`${slug}: metadata.json is not valid JSON (${(e as Error).message})`)
  }
  for (const key of REQUIRED) if (!(key in meta)) errors.push(`${slug}: metadata.json is missing "${key}"`)
  if (!exists(path.join(dir, "page.tsx"))) errors.push(`${slug}: missing page.tsx`)
  if (!exists(path.join(dir, "HOW_IT_WORKS.md"))) errors.push(`${slug}: missing HOW_IT_WORKS.md`)
  if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(slug)) errors.push(`${slug}: folder name must be kebab-case`)

  const light = thumb(`${slug}-light.png`)
  const dark = thumb(`${slug}-dark.png`)
  return {
    slug,
    meta,
    thumbnails: light && dark ? { light, dark } : null,
    og: { image: thumb(`${slug}-og.png`), video: thumb(`${slug}-og.mp4`) },
  }
})

if (errors.length) {
  console.error("Prototype registry errors:\n  " + errors.join("\n  "))
  process.exit(1)
}

const publicOnes = entries.filter((e) => e.meta.public === true)

const out = `// AUTO-GENERATED by scripts/generate-registry.ts. Do not edit.
import type { ComponentType } from "react"
import type { Prototype } from "./prototype-types"

export const prototypes: Prototype[] = ${JSON.stringify(
  entries.map((e) => ({ slug: e.slug, ...e.meta, thumbnails: e.thumbnails, og: e.og })),
  null,
  2
)}

/** Component loaders for PUBLIC prototypes only (used by /p/[slug]). */
export const publicLoaders: Record<string, () => Promise<{ default: ComponentType }>> = {
${publicOnes.map((e) => `  ${JSON.stringify(e.slug)}: () => import("@/app/prototypes/${e.slug}/page"),`).join("\n")}
}
`

// Tiny slug list for proxy.ts (kept separate so the proxy doesn't pull in components).
const slugsFile = path.join(root, "lib", "public-slugs.generated.ts")
const slugsOut = `// AUTO-GENERATED by scripts/generate-registry.ts. Do not edit.
export const publicSlugs: readonly string[] = ${JSON.stringify(publicOnes.map((e) => e.slug))}
`
if (!exists(slugsFile) || fs.readFileSync(slugsFile, "utf8") !== slugsOut) fs.writeFileSync(slugsFile, slugsOut)

const prev = exists(outFile) ? fs.readFileSync(outFile, "utf8") : ""
if (prev !== out) fs.writeFileSync(outFile, out)
console.log(`Registry: ${entries.length} prototype(s), ${publicOnes.length} public.`)
